function emptyEl(text) {
  const e = document.createElement('div'); e.className = 'empty'; e.textContent = text; return e;
}

function actBtn(label, cls, fn) {
  const b = document.createElement('button');
  b.type = 'button'; b.className = 'act' + (cls ? ' ' + cls : ''); b.textContent = label;
  b.addEventListener('click', fn);
  return b;
}

function renderItem(it) {
  const el = document.createElement('div');
  el.className = 'item'; el.id = 'item-' + it.id;
  // A "Reading list" marker only makes sense in the Collection, where read and
  // to-read items sit side by side; the Archive view labels itself.
  const showReadingChip = currentView === 'all' && it.toRead;
  const showArchivedChip = currentView === 'archive';
  el.innerHTML =
    ((showReadingChip || showArchivedChip) ? '<span class="status-chip"></span>' : '') +
    '<div class="title"></div>' +
    (it.desc ? '<div class="desc"></div>' : '') +
    (renderNote(it.note) ? '<div class="note note-body"></div>' : '') +
    ((it.tags && it.tags.length) ? '<div class="tags"></div>' : '') +
    '<a class="url" target="_blank" rel="noopener"></a>' +
    '<div class="foot"><span class="source-line"></span></div>' +
    '<div class="card-dates"></div>' +
    '<div class="card-actions"></div>';
  if (showReadingChip) {
    const chip = el.querySelector('.status-chip');
    chip.classList.add('read'); chip.textContent = 'In reading list';
  } else if (showArchivedChip) {
    const chip = el.querySelector('.status-chip');
    chip.classList.add('archived'); chip.textContent = 'Archived';
  }
  el.querySelector('.title').textContent = it.title;
  if (it.hasPreview) el.insertBefore(previewEl(it.host, it.title), el.firstChild);
  if (it.desc) el.querySelector('.desc').textContent = it.desc;
  const noteHtml = renderNote(it.note);
  if (noteHtml) el.querySelector('.note').innerHTML = noteHtml;
  if (it.tags && it.tags.length) {
    const tg = el.querySelector('.tags');
    it.tags.forEach(t => { const s = document.createElement('span'); s.className = 'tag'; s.textContent = t; tg.appendChild(s); });
  }
  const a = el.querySelector('.url'); a.textContent = it.url; a.href = it.url;
  const sl = el.querySelector('.source-line');
  sl.appendChild(favEl(it.host));
  const hs = document.createElement('span'); hs.textContent = it.host; sl.appendChild(hs);

  const dates = el.querySelector('.card-dates');
  let dtxt = 'Saved ' + fmtDate(it.created);
  if (it.updated && new Date(it.updated).toDateString() !== new Date(it.created).toDateString()) {
    dtxt += ' · Updated ' + fmtDate(it.updated);
  }
  dates.textContent = dtxt;

  const actions = el.querySelector('.card-actions');
  if (currentView === 'archive') {
    actions.appendChild(actBtn('Restore to collection', '', () => mutate(it.id, x => { x.archived = false; })));
  } else if (currentView === 'reading') {
    actions.appendChild(actBtn('Mark as read', 'primary', () => mutate(it.id, x => { x.toRead = false; })));
    actions.appendChild(actBtn('Archive', '', () => mutate(it.id, x => { x.archived = true; })));
  } else { // collection
    if (it.toRead) actions.appendChild(actBtn('Mark as read', '', () => mutate(it.id, x => { x.toRead = false; })));
    else actions.appendChild(actBtn('Add to reading list', 'primary', () => mutate(it.id, x => { x.toRead = true; })));
    actions.appendChild(actBtn('Archive', '', () => mutate(it.id, x => { x.archived = true; })));
  }
  actions.appendChild(actBtn('Edit', '', () => {
    openReview({ id: it.id, url: it.url, host: it.host, title: it.title, desc: it.desc, note: it.note, tags: (it.tags || []).slice(), toRead: it.toRead }, true);
    reviewMount.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }));
  actions.appendChild(actBtn('Delete', 'danger-text', () => {
    // Permanent delete is separate from Archive and requires explicit confirmation.
    actions.innerHTML = '';
    const warn = document.createElement('span');
    warn.className = 'confirm-text';
    warn.textContent = 'Delete for good? This can’t be undone.';
    actions.appendChild(warn);
    actions.appendChild(actBtn('Delete permanently', 'danger', () => {
      items = items.filter(x => x.id !== it.id);
      redraw();
    }));
    actions.appendChild(actBtn('Cancel', '', () => redraw()));
  }));
  return el;
